package org.dyn4j.geometry;

import org.dyn4j.Copyable;
import org.dyn4j.Epsilon;

public class Vector3 implements Copyable<Vector3> {
	public double x;

	public double y;

	public double z;

	public Vector3() {}

	public Vector3(Vector3 vector) {
		this.x = vector.x;
		this.y = vector.y;
		this.z = vector.z;
	}

	public Vector3(double x, double y, double z) {
		this.x = x;
		this.y = y;
		this.z = z;
	}

	public Vector3(double x1, double y1, double z1, double x2, double y2, double z2) {
		this.x = x2 - x1;
		this.y = y2 - y1;
		this.z = z2 - z1;
	}

	public Vector3(Vector3 p1, Vector3 p2) {
		this.x = p2.x - p1.x;
		this.y = p2.y - p1.y;
		this.z = p2.z - p1.z;
	}

	@Override
	public Vector3 copy() {
		return new Vector3(this.x, this.y, this.z);
	}

	public double distance(double x, double y, double z) {
		double xd = this.x - x;
		double yd = this.y - y;
		double zd = this.z - z;
		return Math.sqrt(xd * xd + yd * yd + zd * zd);
	}

	public double distance(Vector3 point) {
		double xd = this.x - point.x;
		double yd = this.y - point.y;
		double zd = this.z - point.z;
		return Math.sqrt(xd * xd + yd * yd + zd * zd);
	}

	public double distanceSquared(double x, double y, double z) {
		double xd = this.x - x;
		double yd = this.y - y;
		double zd = this.z - z;
		return xd * xd + yd * yd + zd * zd;
	}

	public double distanceSquared(Vector3 point) {
		double xd = this.x - point.x;
		double yd = this.y - point.y;
		double zd = this.z - point.z;
		return xd * xd + yd * yd + zd * zd;
	}

	public static Vector3 tripleProduct(Vector3 a, Vector3 b, Vector3 c) {
		Vector3 r = new Vector3();
		double ac = a.x * c.x + a.y * c.y + a.z * c.z;
		double bc = b.x * c.x + b.y * c.y + b.z * c.z;
		r.x = b.x * ac - a.x * bc;
		r.y = b.y * ac - a.y * bc;
		r.z = b.z * ac - a.z * bc;
		return r;
	}

	@Override
	public int hashCode() {
		final int prime = 31;
		int result = 1;
		long temp;
		temp = Double.doubleToLongBits(x);
		result = prime * result + (int) (temp ^ (temp >>> 32));
		temp = Double.doubleToLongBits(y);
		result = prime * result + (int) (temp ^ (temp >>> 32));
		temp = Double.doubleToLongBits(z);
		result = prime * result + (int) (temp ^ (temp >>> 32));
		return result;
	}

	@Override
	public boolean equals(Object obj) {
		if (obj == null) return false;
		if (obj == this) return true;
		if (obj instanceof Vector3) {
			Vector3 other = (Vector3) obj;
			if (this.x == other.x
			 && this.y == other.y
			 && this.z == other.z) {
				return true;
			}
		}
		return false;
	}

	public boolean equals(Vector3 vector) {
		if (vector == null) return false;
		if (this == vector) {
			return true;
		} else {
			return this.x == vector.x && this.y == vector.y && this.z == vector.z;
		}
	}

	public boolean equals(double x, double y, double z) {
		return this.x == x && this.y == y && this.z == z;
	}

    public boolean equals(Vector3 vector, double epsilon) {
        if (vector == null) {
            return false;
        }
        if (vector == this) {
        	return true;
        }
        if (Math.abs(vector.x - this.x) > epsilon) {
        	return false;
        }
        if (Math.abs(vector.y - this.y) > epsilon) {
        	return false;
        }
        if (Math.abs(vector.z - this.z) > epsilon) {
        	return false;
        }
        return true;
    }

	public boolean equals(double x, double y, double z, double epsilon) {
		if (Math.abs(x - this.x) > epsilon) {
        	return false;
        }
        if (Math.abs(y - this.y) > epsilon) {
        	return false;
        }
        if (Math.abs(z - this.z) > epsilon) {
        	return false;
        }
        return true;
	}

	@Override
	public String toString() {
		StringBuilder sb = new StringBuilder();
